'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

const NOTIFICATIONS_COOKIE = 'notifications-enabled'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const current = cookieStore.get(NOTIFICATIONS_COOKIE)?.value === 'true'
  const next = !current

  cookieStore.set(NOTIFICATIONS_COOKIE, String(next), {
    path: '/',
    maxAge: 60 * 60 * 24 * 365, // 1 year
  })

  refresh()
}

